  orange:    "#F97316",
  orangeDim: "#C2531A",
  orangeGlow:"rgba(249,115,22,0.15)",
  blue:      "#3B82F6",
  blueDim:   "#1D4ED8",
  blueGlow:  "rgba(59,130,246,0.15)",
  cyan:      "#06B6D4",
