// ─── Main OmniDash Shell ──────────────────────────────────────────────────────
export default function OmniDashShell() {
  const [tick, setTick] = useState(0);
  const [activeNav, setActiveNav] = useState("OmniBoard");
  const [ops, setOps] = useState({ demo:true, autoPilot:false, guardian:true, live:false });

  useEffect(() => {
    const id = setInterval(() => setTick(t => t+1), 500);
    return () => clearInterval(id);
  }, []);

  return (
    <div style={{
      fontFamily:"-apple-system,BlinkMacSystemFont,'SF Pro Display','Segoe UI',system-ui,sans-serif",
      background: T.bg, color: T.t1,
      width:"100%", height:"100vh",
      display:"flex", flexDirection:"column",
      overflow:"hidden",
    }}>
      <style>{`
        ${pulse} ${shimmer} ${fadeIn} ${scanLine} ${navGlow} ${ringRotate} ${ringBreath} ${ringBreath2}
        * { box-sizing: border-box; margin:0; padding:0; }
        ::-webkit-scrollbar { width:4px; }
        ::-webkit-scrollbar-track { background:transparent; }
        ::-webkit-scrollbar-thumb { background:rgba(255,255,255,0.1); border-radius:2px; }
        button { font-family:inherit; }
        input { font-family:inherit; }
      `}</style>

      <OmniDashHeader tick={tick} />

      <div style={{ flex:1, display:"flex", overflow:"hidden" }}>
        <OmniDashSidebar activeNav={activeNav} setActiveNav={setActiveNav} />

        {/* Main Canvas */}
        <div style={{
          flex:1, display:"flex", flexDirection:"column",
          overflow:"auto", padding:"16px", gap:14,
          background:`radial-gradient(ellipse at 30% 20%,${T.orange}08 0%,transparent 60%),${T.bg}`,
        }}>
          {/* Primary 3-column grid — fixed height ~3 ecosystem tiles tall */}
          <div style={{ display:"grid", gridTemplateColumns:"220px 1fr 220px", gap:14, height:300 }}>
            <AgentWidget tick={tick} />
            <OmniSlateWidget />
            <EcosystemWidget />
          </div>

          {/* Integrated Apps row */}
          <IntegratedAppsWidget />

          {/* APEX-OmniHub wordmark watermark — main canvas background */}
          <div style={{
            flex:1, display:"flex", alignItems:"center", justifyContent:"center",
            pointerEvents:"none", userSelect:"none", minHeight:80,
          }}>
            <img
              src={IMG_APEX_WM}
              alt=""
              style={{
                width:"55%", maxWidth:380,
                objectFit:"contain",
                opacity:0.23,
                filter:"brightness(1.6) saturate(0.4)",
              }}
            />
          </div>
        </div>

        {/* Right Panel */}
        <div style={{
          width:266, flexShrink:0,
          background:`linear-gradient(180deg,${T.surface} 0%,${T.bg} 100%)`,
          borderLeft:`1px solid ${T.border}`,
          overflowY:"auto", padding:"14px 12px",
          display:"flex", flexDirection:"column", gap:12,
        }}>
          <SecurityPanel tick={tick} />
          <AnalyticsPanel />
          <OmniTracePanel />
          <OpsControlsPanel ops={ops} setOps={setOps} />
        </div>
      </div>

      {/* Footer bar */}
      <div style={{
        height:28, background:T.surface,
        borderTop:`1px solid ${T.border}`,
        display:"flex", alignItems:"center",
        padding:"0 20px", gap:16,
        fontSize:9.5, color:T.t3,
      }}>
        <div style={{display:"flex",alignItems:"center",gap:5}}>
          <StatusDot color={T.green} pulse={false} />
          APEX-OmniHub v2.5.0
        </div>
        <div>© 2026 APEX Business Systems Ltd.</div>
        <div style={{marginLeft:"auto", display:"flex", gap:14}}>
          <span>Edmonton, AB</span>
          <span style={{color:T.t4}}>|</span>
          <span>Guardian: ACTIVE</span>
          <span style={{color:T.t4}}>|</span>
          <span style={{color:T.green}}>Zero Trust: ON</span>
        </div>
      </div>
    </div>
  );
}
